-- ============================================================================
-- دفعة السكن: خمسة أنقاض إيجار ← دليل واحد، ونقيضا العدادات ← الدليل الوحش القائم
-- ============================================================================
-- renting-house (252 حرفاً) يُعاد بناؤه دليل الاستئجار الكامل على مرساتين
-- قانونيتين: المادة 342 (سقف الوديعة ثلاثة أشهر وإيداعها باسم المستأجر —
-- الأصل الذي لا يطبّقه أحد وعلى كل مستأجر معرفته) والمادة 344 (سقف الزيادة
-- بمتوسّط TÜFE — بلا رقم منشور، الحاسبة تحسبه)، ومعهما فخّ تعهّد الإخلاء
-- الموقَّع يوم العقد، وحقيقة عقد e-Devlet الرقمي (أواخر 2024، بلا نوتر،
-- معتمد للنفوس) المنقولة من نقض الـ17 قراءة قبل تقاعده.
--
-- وتتقاعد خمسة أنقاض إيجار إلى الدليل، ونقيضا العدادات إلى
-- home-subscriptions-turkey-2026 القائم أصلاً (21,537 حرفاً يغطّي DASK
-- والتأمينات والاسترداد — فُحص حيّاً) — لا بناء في شقّ العدادات إطلاقاً.
--
-- اتّساقٌ مع دليل المستهلك المنشور قبل ساعات: نزاع الإيجار والوديعة خارج
-- اختصاص لجنة التحكيم — مساره مطالبة مكتوبة ثم القضاء المدني.
--
-- الصفوف الثمانية id == slug (فُحص)، ولا روابط واردة لأيٍّ من المتقاعدة.
--
-- آمن لإعادة التشغيل.
-- ============================================================================

UPDATE articles SET
    title = 'استئجار منزل في تركيا 2026: العقد الرقمي، وسقف الوديعة القانوني، وحساب الزيادة، وفخّ تعهّد الإخلاء',
    intro = 'استئجار بيت في تركيا أكثر من توقيع عقد: وديعة لها سقف قانوني لا يعرفه أكثر المستأجرين (ثلاثة أشهر — المادة 342)، وزيادة سنوية سقفها متوسّط TÜFE تحسبها حاسبتنا بدل رقم محفوظ، وعقد رقمي عبر e-Devlet صار معتمداً بلا نوتر، وورقة واحدة — تعهّد الإخلاء — توقيعها يوم العقد يُخرج الناس من بيوتهم بعد سنة. هذا الدليل يرتّبها كلّها.',
    details = '<div style="background:#ecfdf5;border:2px solid #10b981;border-radius:12px;padding:18px 22px;margin:0 0 20px;"><p style="margin:0 0 10px;font-size:17px;"><strong>الخلاصة</strong></p><p style="margin:0;">أربعة أشياء تحسم تجربة استئجارك كلّها: <strong>عقد مكتوب</strong> (والرقمي عبر e-Devlet يعتمد رسمياً)، و<strong>وديعة موثّقة</strong> — وسقفها في القانون ثلاثة أشهر إيجار — و<strong>زيادة سنوية بسقف TÜFE</strong> تحسبها حاسبتنا، و<strong>توقيعك</strong>: لا توقّع تعهّد إخلاء يوم توقيع العقد مهما قيل لك إنّه «روتين».</p></div><h2>العقد: مكتوبٌ دائماً — والرقمي صار معتمداً</h2><p>لا عقد شفهياً مهما بدا المالك طيّباً: العقد المكتوب شرطُ كلّ ما بعده — تثبيت العنوان، والاشتراكات، والإقامة. ومنذ أواخر 2024 تتيح تركيا <strong>عقد الإيجار الرقمي عبر e-Devlet</strong>: يوقّعه الطرفان إلكترونياً، <strong>بلا نوتر</strong>، وهو معتمد لتثبيت العنوان في النفوس. إن كان مؤجّرك مستعدّاً له فهو أنظف مسار؛ وإلا فعقد ورقي بهويّتَي الطرفين وتوقيعهما على كل صفحة.</p><p>وبعد السكن مباشرةً: <strong>ثبّت عنوانك</strong> — واجبٌ بمهلة وتتوقّف عليه معاملاتك كلّها (<a href="/article/syrian-address-update-mandate-turkey">تحديث العنوان الإجباري</a> و<a href="/article/kimlik-data-update">تحديث بيانات الكملك</a>).</p><h2>الوديعة (Depozito): سقفها القانوني ثلاثة أشهر — والتوثيق هو المعركة</h2><p>قانون الموجبات التركي (المادة 342): الوديعة <strong>لا تتجاوز ثلاثة أشهر إيجار</strong>، والأصل في الوديعة النقدية أن <strong>تُودَع في حساب بنكي باسم المستأجر</strong> لا أن تدخل جيب المالك. قليلٌ من يطبّق هذا الأصل — لكن اعرفه: مالكٌ يطلب ستّة أشهر وديعةً يطلب ما لا يحقّ له.</p><p>وعملياً، الوديعة تُخسَر بالتوثيق الناقص لا بالقانون:</p><ul><li><strong>إيصال</strong> بكل ما دفعت (وديعة وإيجاراً) — والتحويل البنكي المعنون «kira» أقوى إثبات (<a href="/article/bank-account-opening">حسابك البنكي</a>).</li><li><strong>صوّر البيت يوم الاستلام</strong> — كلّ عيب موجود قبلك، بتاريخ الصور.</li><li><strong>تسليمٌ موثّق عند الخروج</strong>: جولة مشتركة، وقراءات العدادات، وبراءة من المستحقّات.</li></ul><p>رفض المالك الردّ بلا سبب؟ مطالبة مكتوبة (يفضَّل عبر نوتر) ثم المسار القضائي المدني — <strong>وليست لجنة المستهلك</strong>: نزاعات الإيجار خارج اختصاصها.</p><h2>الزيادة السنوية: سقفها متوسّط TÜFE — ولا رقم ثابتاً</h2><p>الزيادة في العقود السكنية سقفها القانوني (المادة 344) هو <strong>متوسّط مؤشّر أسعار المستهلك لاثني عشر شهراً</strong>، ويتغيّر كل شهر بإعلان هيئة الإحصاء — وحقبة سقف الـ25% المؤقّت انتهت. لا تحفظ رقماً: <a href="/tools/rent-increase-calculator"><strong>احسب سقف زيادتك الشهر الجاري بحاسبتنا ←</strong></a></p><ul><li>الزيادة عند <strong>تجديد السنة</strong> لا في منتصفها.</li><li>طلبُ أكثر من السقف لا يُلزمك — وما دفعتَه زائداً يمكن استرداده.</li><li>وثّق كل اتفاق زيادة كتابةً.</li></ul><h2>الفخّ الذي يُخرج الناس من بيوتهم: تعهّد الإخلاء</h2><p>يُدسّ أحياناً بين أوراق التوقيع <strong>تعهّد إخلاء</strong> (<span dir="ltr">tahliye taahhütnamesi</span>) — ورقة تتعهّد فيها بإخلاء البيت في تاريخ معيّن، وكثيراً ما تكون <strong>بلا تاريخ</strong> يملؤه المالك لاحقاً كما يشاء. توقيعها يوم العقد هو الطريقة النمطية التي يخسر بها المستأجرون بيوتهم بعد سنة. <strong>لا توقّع أي ورقة إخلاء مع العقد</strong> مهما قيل «إجراء شكلي» — والقاعدة العامة: لا توقّع ما لم تفهمه، ولا ورقةً فارغة التاريخ أبداً.</p><h2>العائدات (Aidat) — من يدفع ماذا؟</h2><p>في المجمّعات، الـAidat تغطّي خدمات التشغيل (نظافة، أمن، مصعد…) وتقع عادةً على <strong>الساكن</strong>؛ أمّا نفقات الملكية الكبرى (تجديدات هيكلية) فمنطقها على <strong>المالك</strong> — وحدّدا ذلك في العقد صراحةً قطعاً للنزاع. وارتفعت العائدات فجأة بلا تفسير؟ اطلب <strong>ميزانية الموقع مكتوبةً</strong> من الإدارة — حقّك — وقدّم اعتراضك كتابةً للإدارة واجتماع الملّاك.</p><h2>الجيران والضوضاء: التدرّج يحميك</h2><p>تفاهمٌ هادئ أولاً، ثم إدارة المجمّع كتابةً، ثم التوثيق (تواريخ، تسجيلات، شهود)، ثم البلاغ عند الضرورة (زابطة البلدية للإزعاج، والشرطة لما يتجاوزه). القفز فوق الدرجات ينقلب عليك — والتوثيق هو ما يفصل شكواك عن «كلام جيران».</p><h2>العدادات والاشتراكات — دليلها المستقل</h2><p>فتح الكهرباء والماء والغاز والإنترنت باسمك، وDASK الإلزامي، وتأمينات العدادات واستردادها عند الخروج — كلّه مفصَّل في <a href="/article/home-subscriptions-turkey-2026"><strong>دليل اشتراكات المنزل الكامل ←</strong></a></p><h2>أسئلة متكرّرة</h2><h3>المالك يرفض عقداً مكتوباً — «كلمة شرف»؟</h3><p>ارحل. بلا عقد لا تثبيت عنوان ولا اشتراكات باسمك ولا إثبات لأي حقّ — و«كلمة الشرف» لا تُبرَز في نزاع.</p><h3>دفعت وديعةً نقداً بلا إيصال — ماذا الآن؟</h3><p>اطلب الإيصال اليوم قبل أي خلاف، أو حوّل ما بقي من دفعاتك بنكياً بعنوان واضح — فالإثبات يُبنى من الآن فصاعداً على الأقل.</p><h3>هل يطردني المالك إن رفضت زيادةً فوق السقف؟</h3><p>رفضُ زيادةٍ غير قانونية ليس سبب إخلاء. أسباب الإخلاء محدّدة قانوناً — وهنا يظهر خطر تعهّد الإخلاء الموقَّع سلفاً: لا تعطِ أحداً سلاحاً جاهزاً.</p>',
    steps = ARRAY['قبل التوقيع: اقرأ كل ورقة — ولا توقّع تعهّد إخلاء ولا ورقة فارغة التاريخ أبداً.', 'اعقد كتابةً: عقد e-Devlet الرقمي إن أمكن (بلا نوتر ومعتمد للنفوس)، أو ورقي بهويتي الطرفين.', 'وثّق الوديعة: سقفها 3 أشهر قانوناً — إيصال أو تحويل بنكي معنون، وصور البيت يوم الاستلام.', 'ثبّت عنوانك في النفوس فور السكن — ثم افتح الاشتراكات باسمك (دليل الاشتراكات).', 'عند التجديد: احسب سقف الزيادة بالحاسبة ولا تقبل رقماً محفوظاً.', 'عند الخروج: جولة تسليم مشتركة، وقراءات عدادات، واسترداد الوديعة والتأمينات موثَّقاً.', 'وعند النزاع: مطالبة مكتوبة أولاً — ونزاع الإيجار مساره قضائي مدني لا لجنة المستهلك.']::text[], tips = ARRAY['سقف الوديعة ثلاثة أشهر إيجار بنصّ المادة 342 — من طلب ستّة طلب ما لا يحقّ له.', 'تعهّد الإخلاء الموقَّع يوم العقد هو الطريقة النمطية لخسارة البيت بعد سنة — لا توقّعه.', 'عقد e-Devlet الرقمي بلا نوتر ومعتمد لتثبيت العنوان — اسأل مؤجّرك عنه أولاً.', 'سقف الزيادة متوسّط TÜFE لاثني عشر شهراً ويتغيّر شهرياً — الحاسبة لا الذاكرة.', 'صور يوم الاستلام بتاريخها = وديعتك عند الخروج.', 'الزيادة عند تجديد السنة فقط — ومنتصف العقد ليس موسمها.']::text[], documents = ARRAY['هويتا الطرفين (كملك/إقامة/جواز) للعقد', 'العقد المكتوب أو الرقمي عبر e-Devlet — نسخة كاملة بيدك', 'إيصالات الوديعة والإيجار (أو حركات التحويل البنكي المعنونة)', 'صور حالة البيت يوم الاستلام ويوم التسليم، وقراءات العدادات']::text[],
    fees = 'لا رسم على العقد الرقمي عبر e-Devlet. والوديعة سقفها القانوني ثلاثة أشهر إيجار. وسقف الزيادة السنوية متوسّط TÜFE المعلن شهرياً — احسبه بالحاسبة ولا تعتمد رقماً متداولاً.', warning = 'لا توقّع تعهّد إخلاء مع العقد ولا أي ورقة فارغة التاريخ. والوديعة فوق ثلاثة أشهر مخالفة للمادة 342. ونزاعات الإيجار خارج اختصاص لجنة المستهلك — مسارها مدني. والعقد الشفهي يترك كل حقوقك بلا إثبات.', source = 'قانون الموجبات التركي (TBK) رقم 6098 — المادة 342 (سقف الوديعة ثلاثة أشهر وإيداعها باسم المستأجر) والمادة 344 (سقف الزيادة بمتوسّط TÜFE لاثني عشر شهراً)؛ وخدمة عقود الإيجار الرقمية عبر e-Devlet (أواخر 2024، بلا نوتر، معتمدة لتثبيت العنوان)؛ ومؤشّر TÜFE الشهري لهيئة الإحصاء TÜİK', tags = ARRAY['الإيجار', 'السكن والحياة', 'الوديعة', 'زيادة الإيجار', 'دليل', '2026']::text[],
    category = 'السكن والحياة', seo_title = 'استئجار منزل في تركيا: العقد والوديعة وسقف الزيادة وفخّ الإخلاء', seo_description = 'سقف الوديعة 3 أشهر بنص القانون، والزيادة بمتوسط TÜFE تحسبها حاسبتنا، وعقد e-Devlet الرقمي بلا نوتر — وفخّ تعهّد الإخلاء الذي يُخرج المستأجرين من بيوتهم. دليل الاستئجار الكامل للأجانب والسوريين.',
    last_update = CURRENT_DATE
WHERE slug = 'renting-house';

UPDATE articles SET status = 'draft', last_update = CURRENT_DATE
WHERE slug IN ('rent-increase-limit', 'deposit-return', 'digital-lease-contract', 'housing-advanced-aidat-dispute', 'housing-advanced-neighbor-noise', 'utilities-registration', 'exit-utility-deposit-refund') AND status = 'approved';

-- ═══════════════════════════════════════════════════════════════════════════
DO $check$
DECLARE n int;
BEGIN
    SELECT count(*) INTO n FROM articles
     WHERE slug = 'renting-house' AND status = 'approved'
       AND details LIKE '%342%' AND details LIKE '%tahliye%';
    IF n <> 1 THEN RAISE EXCEPTION 'the rent rebuild did not land'; END IF;

    SELECT count(*) INTO n FROM articles
     WHERE slug = 'home-subscriptions-turkey-2026' AND status = 'approved' AND length(details) > 15000;
    IF n <> 1 THEN RAISE EXCEPTION 'the utilities canonical is not intact'; END IF;

    SELECT count(*) INTO n FROM articles WHERE slug IN ('rent-increase-limit', 'deposit-return', 'digital-lease-contract', 'housing-advanced-aidat-dispute', 'housing-advanced-neighbor-noise', 'utilities-registration', 'exit-utility-deposit-refund') AND status = 'approved';
    IF n > 0 THEN RAISE EXCEPTION '% stub(s) still approved', n; END IF;
END
$check$;

SELECT 'rent guide rebuilt (art 342 + 344 + tahliye trap)' AS البند,
       (details LIKE '%342%' AND details LIKE '%344%')::text AS النتيجة
FROM articles WHERE slug = 'renting-house'
UNION ALL
SELECT 'utilities canonical intact (>15K chars)', (length(details) > 15000)::text
FROM articles WHERE slug = 'home-subscriptions-turkey-2026'
UNION ALL
SELECT 'seven stubs retired (want 0 approved)', count(*)::text
FROM articles WHERE slug IN ('rent-increase-limit', 'deposit-return', 'digital-lease-contract', 'housing-advanced-aidat-dispute', 'housing-advanced-neighbor-noise', 'utilities-registration', 'exit-utility-deposit-refund') AND status = 'approved';
